selector_to_html = {"a[href=\"#flaggems-control\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">FlagGems Control<a class=\"headerlink\" href=\"#flaggems-control\" title=\"Link to this heading\">#</a></h3><p><strong>Priority</strong>: <code class=\"docutils literal notranslate\"><span class=\"pre\">WHITELIST</span></code> &gt; (<code class=\"docutils literal notranslate\"><span class=\"pre\">BLACKLIST</span></code> env or platform <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos_blacklist</span></code>) + <code class=\"docutils literal notranslate\"><span class=\"pre\">BLACKLIST_APPEND</span></code></p>", "a[href=\"#supported-operators\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Supported operators<a class=\"headerlink\" href=\"#supported-operators\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#fallback-mechanism\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Fallback mechanism<a class=\"headerlink\" href=\"#fallback-mechanism\" title=\"Link to this heading\">#</a></h3><p>When <code class=\"docutils literal notranslate\"><span class=\"pre\">VLLM_FL_STRICT=0</span></code> (default), if the primary implementation fails, the system automatically tries other available implementations:</p>", "a[href=\"#operator-list\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Operator List<a class=\"headerlink\" href=\"#operator-list\" title=\"Link to this heading\">#</a></h2><p>This reference lists all operators supported by vllm-plugin-FL and their backend availability.</p>", "a[href=\"#user-specified-configuration-file-yaml\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">User-specified configuration file (YAML)<a class=\"headerlink\" href=\"#user-specified-configuration-file-yaml\" title=\"Link to this heading\">#</a></h2><p>Set the <code class=\"docutils literal notranslate\"><span class=\"pre\">VLLM_FL_CONFIG</span></code> environment variable to specify a YAML configuration file that completely overrides all other settings:</p>", "a[href=\"#example-combined-environment-variables\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Example: Combined environment variables<a class=\"headerlink\" href=\"#example-combined-environment-variables\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#platform-specific-configuration\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Platform-specific configuration<a class=\"headerlink\" href=\"#platform-specific-configuration\" title=\"Link to this heading\">#</a></h2><p>The system detects the hardware platform from the vLLM platform\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">vendor_name</span></code> and loads the matching configuration file from the <code class=\"docutils literal notranslate\"><span class=\"pre\">config/</span></code> directory. Each platform config sets the preferred backend, the per-operator backend order, and the FlagGems/OOT blacklists.</p>", "a[href=\"#debug-logging\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Debug &amp; Logging<a class=\"headerlink\" href=\"#debug-logging\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#whitelist-vs-blacklist-priority\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Whitelist vs Blacklist Priority<a class=\"headerlink\" href=\"#whitelist-vs-blacklist-priority\" title=\"Link to this heading\">#</a></h3><p>For FlagGems and OOT operators:</p>", "a[href=\"#examples\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Examples<a class=\"headerlink\" href=\"#examples\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#oot-operator-control\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">OOT Operator Control<a class=\"headerlink\" href=\"#oot-operator-control\" title=\"Link to this heading\">#</a></h3><p><strong>Priority</strong>: <code class=\"docutils literal notranslate\"><span class=\"pre\">WHITELIST</span></code> &gt; <code class=\"docutils literal notranslate\"><span class=\"pre\">BLACKLIST</span></code> (env) &gt; <code class=\"docutils literal notranslate\"><span class=\"pre\">oot_blacklist</span></code> (config file)</p>", "a[href=\"#environment-variables\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Environment variables<a class=\"headerlink\" href=\"#environment-variables\" title=\"Link to this heading\">#</a></h2><p>Environment variables can override specific items from platform config. If not set, values from platform config file are used.</p>", "a[href=\"#plugins\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Plugins<a class=\"headerlink\" href=\"#plugins\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#example-configuration-file\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Example configuration file<a class=\"headerlink\" href=\"#example-configuration-file\" title=\"Link to this heading\">#</a></h3><h4>Token type explanations<a class=\"headerlink\" href=\"#token-type-explanations\" title=\"Link to this heading\">#</a></h4><p><strong>Note</strong>: When using <code class=\"docutils literal notranslate\"><span class=\"pre\">vendor</span></code> (without specifying a vendor name), the system automatically selects an available vendor backend based on hardware detection.</p>", "a[href=\"#more-op-backends-selection-example\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">More op backends selection example<a class=\"headerlink\" href=\"#more-op-backends-selection-example\" title=\"Link to this heading\">#</a></h4>", "a[href=\"#backend-selection\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Backend Selection<a class=\"headerlink\" href=\"#backend-selection\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#backend-priorities\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Backend priorities<a class=\"headerlink\" href=\"#backend-priorities\" title=\"Link to this heading\">#</a></h3><p>The dispatch system selects operators based on the following priority hierarchy. Priority values are spaced by 50 to allow future insertion of intermediate priorities.</p>", "a[href=\"#core-configuration\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Core Configuration<a class=\"headerlink\" href=\"#core-configuration\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#token-type-explanations\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Token type explanations<a class=\"headerlink\" href=\"#token-type-explanations\" title=\"Link to this heading\">#</a></h4><p><strong>Note</strong>: When using <code class=\"docutils literal notranslate\"><span class=\"pre\">vendor</span></code> (without specifying a vendor name), the system automatically selects an available vendor backend based on hardware detection.</p>", "a[href=\"#other-environment-variables\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Other environment variables<a class=\"headerlink\" href=\"#other-environment-variables\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#configure-backend-selection\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Configure backend selection<a class=\"headerlink\" href=\"#configure-backend-selection\" title=\"Link to this heading\">#</a></h1><p>The dispatch system supports multiple ways to configure backend selection:</p>", "a[href=\"#configuration-priority\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Configuration priority<a class=\"headerlink\" href=\"#configuration-priority\" title=\"Link to this heading\">#</a></h2><p>The dispatch system applies configuration in the following order:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
